(async () => {
  const S = (k) => window.tldraw.createShapeId(k)
  const relabel = (k, title) => window.canvas.step(S(k), () => {
    const s = editor.getShape(S(k))
    editor.updateShape({ id: s.id, type: 'mock', props: { data: { ...s.props.data, title } } })
