  await relabel('bucket', 'Railway bucket (S3-compatible)')
  await relabel('db', 'Railway Postgres')
  const notes = window.canvas.notes()
  editor.deleteShapes(notes.flatMap((n) => [n.id, ...n.arrows]))
  return notes.length
})()
EOF
