cat > /tmp/canvas/spread.js <<'EOF'
(() => {
  const origins = { o1: [0, 0, 0, 0], o2: [1100, 0, 1450, 0], o3: [0, 840, 0, 960], o4: [1100, 840, 1450, 960] }
  const sx = 1.35, sy = 1.2
  const updates = []
  for (const s of editor.getCurrentPageShapes()) {
    if (s.type === 'arrow') continue
    const p = s.id.replace('shape:', '').slice(0, 2)
    const o = origins[p]
    if (o == null) continue
    const lx = s.x - o[0], ly = s.y - o[1]
    const u = { id: s.id, type: s.type, x: o[2] + lx * sx, y: o[3] + ly * sy }
    if (s.id.endsWith('-area')) u.props = { w: 1000 * sx, h: 740 * sy }
    if (s.type === 'text') u.props = { w: 560 }
    updates.push(u)
  }
  editor.updateShapes(updates)
  editor.zoomToFit()
  return updates.length
})()
EOF
