cat > /tmp/canvas/explode.js <<'EOF'
(async () => {
  const { createShapeId: sid, toRichText: rt } = window.tldraw
  const step = (at, fn) => window.canvas.step(at, fn, 350)
  const id = (k) => sid(`wf-${k}`)
  const oy = 2000

  const box = (k, x, y, w, h, text, color = 'black') => step({ x: x + w / 2, y: oy + y + h / 2 }, () => {
    editor.createShape({ id: id(k), type: 'geo', x, y: oy + y, props: { geo: 'rectangle', w, h, richText: rt(text), font: 'draw', size: 's', color, labelColor: 'black' } })
  })
  const store = (k, x, y, w, h, title, caption) => step({ x: x + w / 2, y: oy + y + h / 2 }, () => {
    editor.createShape({ id: id(k), type: 'mock', x, y: oy + y, props: { w, h, kind: 'cylinder', data: { title, caption } } })
  })
  const arrow = (from, to, label = '', bend = 0) => step(id(to), () => {
    const aid = id(`ar-${from}-${to}`)
    const a = editor.getShapePageBounds(id(from)).center
    const b = editor.getShapePageBounds(id(to)).center
    editor.createShape({ id: aid, type: 'arrow', x: a.x, y: a.y, props: { start: { x: 0, y: 0 }, end: { x: b.x - a.x, y: b.y - a.y }, bend, richText: rt(label), size: 's', font: 'draw', color: 'black', labelColor: 'black' } })
    const bind = (target, terminal) => ({ type: 'arrow', fromId: aid, toId: id(target), props: { terminal, normalizedAnchor: { x: 0.5, y: 0.5 }, isExact: false, isPrecise: false } })
    editor.createBindings([bind(from, 'start'), bind(to, 'end')])
  })

  await step({ x: 1500, y: oy + 60 }, () => {
    editor.createShape({ id: id('area'), type: 'mock', x: 0, y: oy, props: { w: 2950, h: 640, kind: 'area', data: { label: 'Item Workflow, step by step (options A and C; pipeline/, TypeScript)' } } })
    editor.sendToBack([id('area')])
  })

  const X = (i) => 40 + i * 360
  const steps = [
    ['s1', '1. Fetch the page'],
    ['s2', "2. Wait for the domain's lease\n(DomainQueue)"],
    ['s3', '3. Run the recipe in the sandbox;\nFlue agents author or revise it'],
    ['s4', '4. Images: fetch,\nSVG → PNG, re-encode WebP'],
    ['s5', '5. Describe images'],
    ['s6', '6. Spawn TTS'],
    ['s7', '7. Sleep and poll TTS\nuntil it finishes'],
    ['s8', '8. Store audio, mark ready'],
  ]
  const below = {
    s1: ['box', 'firecrawl', 'Firecrawl'],
    s3: ['store', 'd1', 'D1', 'items · recipe versions · costs'],
    s4: ['box', 'hosts', 'Image hosts'],
    s5: ['box', 'gemini', 'Gemini'],
    s6: ['box', 'modal', 'Modal TTS\n(HTTP endpoints)', 'violet'],
    s8: ['store', 'r2', 'R2', 'audio · images'],
  }

  for (const [i, [k, text]] of steps.entries()) {
    await box(k, X(i), 90, 290, 110, text, 'orange')
    if (i > 0) await arrow(steps[i - 1][0], k)
    const b = below[k]
    if (b != null) {
      if (b[0] === 'box') await box(b[1], X(i) + 35, 330, 220, 90, b[2], b[3])
      else await store(b[1], X(i) + 50, 300, 190, 160, b[2], b[3])
    }
    if (k === 's1') await arrow('s1', 'firecrawl', 'scrape HTML')
    if (k === 's3') await arrow('s3', 'd1', 'new recipe version')
    if (k === 's4') await arrow('s4', 'hosts', 'fetch')
    if (k === 's5') await arrow('s5', 'gemini', 'describe')
    if (k === 's6') await arrow('s6', 'modal', 'spawn')
    if (k === 's7') await arrow('s7', 'modal', 'poll')
    if (k === 's8') {
      await arrow('s8', 'r2', 'audio')
      await arrow('s4', 'r2', 'images', -0.0)
      await arrow('s8', 'd1', 'units · timing · cost · ready', 0)
    }
  }

  await step({ x: 200, y: oy + 560 }, () => {
    editor.createShape({ id: id('note'), type: 'text', x: 40, y: oy + 520, props: { richText: rt('Every step writes the item status to D1, so GET /items/{id} only reads it. A failed step is retried by the Workflow, which takes over from the queued_at ceiling and the retry route.'), size: 's', font: 'draw', color: 'black', autoSize: false, w: 900 } })
  })
  await arrow('note', 'd1')
  return 'ok'
})()
EOF
