(() => {
  const ups = []
  for (const s of editor.getCurrentPageShapes()) {
    const k = s.id.replace('shape:', '')
    if (!k.startsWith('wf-') || k === 'wf-area' || s.type === 'arrow') continue
    ups.push({ id: s.id, type: s.type, y: s.y + 90 })
  }
  editor.updateShapes(ups)
  const A = (k) => window.tldraw.createShapeId(k)
  editor.updateShape({ id: A('wf-area'), type: 'mock', props: { h: 760 } })
  editor.updateShape({ id: A('wf-ar-s8-d1'), type: 'arrow', props: { bend: -260, labelPosition: 0.5 } })
  editor.updateShape({ id: A('wf-ar-s4-r2'), type: 'arrow', props: { bend: 260 } })
  return ups.length
})()
EOF
