(async () => {
  const { createShapeId, toRichText } = window.tldraw;
  const titles = ['1 Stored data','2 Components and bindings','3 Contracts between deployables','4 Item lifecycle','5 Item Workflow','6 Image handling','7 Delivery to clients','8 Local development','9 Deployment and switchover'];
  const W = 2400, H = 260, GX = 200, GY = 150, TOP = 700;
  const noteId = createShapeId('claude-tree');
  await canvas.step({ x: 600, y: 300 }, () => editor.createShape({
    id: noteId, type: 'geo', x: 0, y: 0,
    props: { geo: 'rectangle', w: 2400, h: 560, dash: 'dashed', color: 'grey', fill: 'none', font: 'sans', size: 's', align: 'start', verticalAlign: 'start',
      richText: toRichText(`Claude

The opening tree is the nine areas below, one per branch, all pending. They run from abstract to concrete: what is stored, which components exist and what binds them, what crosses between deployables, then the item's lifecycle, the Workflow's steps, images, delivery, local development and deployment.

Every decision from shape.md goes into its branch as a ✓ leaf when the branch opens, and only what shape left undecided becomes a question.

Testing is not a branch: shape settled its approach, and the test cases belong to mahou:test-design after the program design.

Correct the tree with sticky notes (add, drop, merge, reorder or rename branches), then press Send to Claude. Branch 1 opens when you approve.`) },
  }));
  for (let i = 0; i < titles.length; i++) {
    const col = Math.floor(i / 3), row = i % 3;
    const id = createShapeId('branch-' + (i + 1));
    await canvas.step({ x: col * (W + GX) + 200, y: TOP + row * (H + GY) + 40 }, () => editor.createShape({
      id, type: 'mock', x: col * (W + GX), y: TOP + row * (H + GY),
      props: { kind: 'area', w: W, h: H, data: { label: titles[i] + ' · pending' } },
    }), 300);
  }
  return 'ok';
})()
EOF
