  editor.updateShape({ id: area.id, type: 'mock', props: { h: newH } });
  for (const n of ['branch-2', 'branch-3']) { const s = editor.getShape(id(n)); editor.updateShape({ id: s.id, type: 'mock', y: s.y + dy }); }
  editor.zoomToBounds(editor.getShapePageBounds(area.id), { inset: 20 });
  return dy;
})()
