  const arrow = (n, from, to, label) => {
    editor.createShape({ id: id(n), type: 'arrow', x: 0, y: 0, props: { color: 'black', font: 'draw', size: 's', richText: toRichText(label), start: { x: 0, y: 0 }, end: { x: 10, y: 0 } } });
    for (const [terminal, target] of [['start', from], ['end', to]]) editor.createBindings([{ type: 'arrow', fromId: id(n), toId: id(target), props: { terminal, normalizedAnchor: { x: 0.5, y: 0.5 }, isExact: false, isPrecise: false } }]);
  };
  const API = ['rectangle', 'blue', 'API Worker'], WF = ['rectangle', 'green', 'item Workflow\n(pipeline Worker)'], MODAL = ['cloud', 'violet', 'Modal TTS'];
  let y = bounds(id('b3-intro')).y + bounds(id('b3-intro')).h + 60;
  const place = (n, g) => { const s = editor.getShape(id(n)); editor.updateShape({ id: s.id, type: s.type, y }); y += bounds(s.id).h + g; };
  const row = async (k, caption, L, R, label, src) => {
    editor.createShape({ id: id(k + '-cap'), type: 'text', x: X, y, props: { font: 'draw', size: 'm', autoSize: false, w: 1160, textAlign: 'start', richText: toRichText(caption) } });
    await sleep(80);
    y += bounds(id(k + '-cap')).h + 20;
    const top = y;
    await canvas.step({ x: X + 120, y: top + 50 }, () => geo(k + '-l', X, top, 240, 100, { geo: L[0], color: L[1], fill: 'semi' }, L[2]));
    await canvas.step({ x: X + 640, y: top + 50 }, () => geo(k + '-r', X + 520, top - (R[0] === 'cloud' ? 15 : 0), 240, R[0] === 'cloud' ? 130 : 100, { geo: R[0], color: R[1], fill: 'semi' }, R[2]));
    await canvas.step({ x: X + 380, y: top + 50 }, () => arrow(k + '-a', k + '-l', k + '-r', label));
    await sleep(100);
    editor.groupShapes([k + '-l', k + '-r', k + '-a'].map(id));
    await canvas.step({ x: X + 1000, y: top + 50 }, () => editor.createShape({ id: id(k + '-cls'), type: 'mock', x: X + 840, y: top, props: { kind: 'mermaid', w: 500, h: 200, data: { source: src } } }), 1200);
    const vb = document.querySelector('[data-shape-id="shape:' + k + '-cls"] svg')?.getAttribute('viewBox')?.split(' ').map(Number);
    if (vb) editor.updateShape({ id: id(k + '-cls'), type: 'mock', props: { w: Math.round(vb[2]), h: Math.round(vb[3]) } });
    y = top + Math.max(130, vb ? Math.round(vb[3]) : 200) + 50;
  };
  place('b3-h1', 40);
  await row('b3-x-create', 'create · at enqueue', API, WF, 'create', M.create);
  await row('b3-x-restart', 'restart · on retry', API, WF, 'restart', M.restart);
  await row('b3-x-status', 'status · on poll', API, WF, 'status', M.status);
  y += 10;
  place('b3-p1', 60);
  place('b3-h2', 40);
  await row('b3-x-start', 'start · once per synthesis', WF, MODAL, 'start', M.start);
  await row('b3-x-result', 'result · polled until ready', WF, MODAL, 'result', M.result);
  y += 10;
  place('b3-p2', 50);
  editor.updateShape({ id: id('b3-claude'), type: 'geo', y, props: { growY: 0, h: 80, richText: toRichText("Claude\n\nEach method now has its own row: a small map of the two components with the call as the arrow, and beside it a class diagram of what the call takes and returns. 3.1 has create, restart and status; 3.2 has start and result.\n\nA finding for branch 4: restart needs the name of the step to restart from, and status() through the binding does not name the step that failed; Cloudflare's REST API for an instance lists every step with its result (wiki cloudflare/workflows). Branch 4, on retry, has to settle how the API learns that step.\n\nTell me what to change, or approve branch 3, then press Send to Claude.") } });
  await sleep(100);
  const c = bounds(id('b3-claude'));
  editor.updateShape({ id: area.id, type: 'mock', props: { h: Math.max(c.y + c.h + 40, area.y + 80 + bounds(id('b3-leaves')).h + 40) - area.y } });
  editor.selectNone();
  editor.zoomToBounds({ x: X - 40, y: bounds(id('b3-h1')).y - 40, w: 1900, h: c.y - bounds(id('b3-h1')).y + 300 });
  return 1;
})()
EOF
