  await sleep(150);
  y += bounds(id('b4-claude')).h + 40;
  const newH4 = Math.max(y, a4.y + 80 + bounds(id('b4-leaves')).h + 40) - a4.y, dy = newH4 - a4.props.h;
  editor.updateShape({ id: a4.id, type: 'mock', props: { h: newH4 } });
  for (const n of ['branch-5', 'branch-6']) { const s = editor.getShape(id(n)); editor.updateShape({ id: s.id, type: 'mock', y: s.y + dy }); }
  editor.zoomToBounds(bounds(a4.id), { inset: 20 });
  return hits;
})()
EOF
