p='design.md'; s=open(p).read()
R=[
("common/ owns the shapes of the item row, the unit list and the item Workflow's params and output","common/ owns the shapes of the item row, the unit list and the item Workflow's params"),
("The shapes of the item row, the unit list and the item Workflow's params and output are TypeScript types in common/","The shapes of the item row, the unit list and the item Workflow's params are TypeScript types in common/"),
("The Workflow returns what the extraction Workflow returns today: the title, the units and the verdict","The Workflow returns no output; everything it produces goes into the row"),
("The params and output types, and the unit union, live in common/","The params type and the unit union live in common/"),
(", and returns the article's title, its units and the extraction verdict as its output; the verdict is empty when extraction succeeded. The param and output types live in common/",", and returns no output. The param type lives in common/"),
("│  ✓ The Workflow returns the title, the units and the verdict\n","│  ✓ The Workflow returns no output; everything it produces goes into the row\n"),
("The Workflow returns the title, the units and the verdict as its output.","The Workflow returns no output; everything it produces is on the row."),
]
for a,b in R:
    if a not in s: print("MISSING",a[:60])
    s=s.replace(a,b)
s=s.replace("│  ✓ Each module inside pipeline/ is as independent of the others as it can be\n","│  ✓ Each module inside pipeline/ is as independent of the others as it can be\n│  ❔ Q14 Which status the wrapper writes for the steps before the domain's lease\n│  ❔ Q15 Which situations around the domain's lease to consider now\n",1)
open(p,'w').write(s)
def lines(num):
    L=s.split("\n"); st=[i for i,l in enumerate(L) if re.match(rf"[├└]─ {num} ",l)][0]; o=[]
    for l in L[st+1:]:
        if re.match(r"[├└]─ \d ",l): break
        o.append(l[3:])
    return o
def wrap(ls):
    res=[]
    for l in ls:
        m=re.match(r"^((?:[│ ]  )*)(├─ |└─ |✓ |❔ )(.*)$", l)
        if not m: continue
        pre,mark,txt=m.groups()
        if mark in ("├─ ","└─ "): res+=["",pre+mark+txt]; continue
        w=textwrap.wrap(txt, 64-len(pre)); res.append(pre+mark+w[0]); res+=[pre+"  "+c for c in w[1:]]
    return "\n".join(res).lstrip("\n")
json.dump({'R':[r for r in R if '\n' not in r[0]],'L':{n:wrap(lines(n)) for n in ['1','3','5']}},open('/tmp/drop.json','w'))
