(async () => {
  const { createShapeId, toRichText } = window.tldraw;
  const id = n => createShapeId(n);
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const b = n => editor.getShapePageBounds(id(n));
  editor.deleteShapes([id('b9-claude')]);
  const a9 = editor.getShape(id('branch-9'));
  editor.updateShape({ id: a9.id, type: 'mock', props: { h: Math.max(b('b9-prose').y + b('b9-prose').h + 40, a9.y + 80 + b('b9-leaves').h + 40) - a9.y } });
  await sleep(100);
  const X = a9.x, Y = a9.y + editor.getShape(a9.id).props.h + 150;
  await canvas.step({ x: X + 400, y: Y + 20 }, () => editor.createShape({ id: id('branch-10'), type: 'mock', x: X, y: Y, props: { kind: 'area', w: a9.props.w, h: 300, data: { label: '10 The common/ package · open' } } }));
  editor.sendToBack([id('branch-10')]);
  const leaves = `✓ common/ is a package both Workers build from; of its contents
  only the migrations are deployed
✓ It holds the types api/ and pipeline/ share: the item row, the
  unit union and the item Workflow's params
✓ It holds the hand-written SQL migrations, applied with wrangler
  by common/'s own CI job before the pipeline and the API deploy
✓ It holds our TypeScript copy of vcrpy, which replays the existing
  cassettes with today's matching rules and filters; replay only
✓ A request that matches no recorded response fails the test
✓ A change to common/ runs both Workers' type checks
❔ Q16 Whether the shared types are checked at runtime
❔ Q17 What else common/ holds`;
  const prose = `common/ is the package api/ and pipeline/ both build from. It holds the TypeScript types the two Workers share, the item row, the unit union and the item Workflow's params, so both build against the same shapes, and a change to it runs both Workers' type checks. It holds the hand-written SQL migrations for the D1 database, which common/'s own CI job applies with wrangler before the pipeline and the API deploy; nothing else in it is deployed. It also holds our TypeScript copy of vcrpy, which replays the existing cassettes with today's matching rules and filters and fails a test on any request no recorded response matches.`;
  await canvas.step({ x: X + 300, y: Y + 150 }, () => editor.createShape({ id: id('b10-leaves'), type: 'text', x: X + 40, y: Y + 80, props: { font: 'mono', size: 's', autoSize: false, w: 1080, textAlign: 'start', richText: toRichText(leaves) } }));
  await canvas.step({ x: X + 1500, y: Y + 150 }, () => editor.createShape({ id: id('b10-prose'), type: 'text', x: X + 1200, y: Y + 80, props: { font: 'draw', size: 's', autoSize: false, w: 1160, textAlign: 'start', richText: toRichText(prose) } }));
  await sleep(100);
  let y = Y + 80 + b('b10-prose').h + 50;
  const card = (n, yy, text) => ({ id: id(n), type: 'geo', x: X + 1200, y: yy, props: { geo: 'rectangle', w: 1160, h: 80, color: 'violet', labelColor: 'black', fill: 'solid', font: 'draw', size: 's', align: 'start', verticalAlign: 'start', richText: toRichText(text) } });
  editor.createShape(card('b10-q16', y, `❓ Q16 · Whether the shared types are checked at runtime

